import 'package:flutter/material.dart';class DueDateCalculator extends StatefulWidget{final Color accentColor;const DueDateCalculator({super.key,this.accentColor=const Color(0xFFE91E63)});@override State<DueDateCalculator>createState()=>_DueDateCalculatorState();}class _DueDateCalculatorState extends State<DueDateCalculator>{DateTime? lmp,due;Future<void>_pick()async{final d=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime.now(),initialDate:lmp??DateTime.now());if(d!=null)setState((){lmp=d;due=d.add(const Duration(days:280));});}@override Widget build(BuildContext c)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('حاسبة تاريخ الولادة',style:TextStyle(fontWeight:FontWeight.w800,color:widget.accentColor,fontSize:17)),const SizedBox(height:10),ListTile(contentPadding:EdgeInsets.zero,title:Text(lmp==null?'اختر تاريخ آخر دورة':'آخر دورة: ${lmp!.day}/${lmp!.month}/${lmp!.year}'),trailing:const Icon(Icons.calendar_today),onTap:_pick),if(due!=null)Container(width:double.infinity,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:widget.accentColor.withOpacity(.08),borderRadius:BorderRadius.circular(12)),child:Text('تاريخ الولادة المتوقع: ${due!.day}/${due!.month}/${due!.year}',style:const TextStyle(fontWeight:FontWeight.w700))) ])));}
